{"content":""""Independent checker for merged_users.parquet / conflicts.json.

Re-derives the expected result straight from the raw source files (without
importing merge_users.py) and compares it with the produced artifacts.
Exits non-zero on any mismatch.
"""
import json
import os
import sys

import pandas as pd

BASE = os.path.dirname(os.path.abspath(__file__))
SOURCES = ["source_a", "source_b", "source_c"]
ALIASES = {
    "user_id": ["user_id", "id", "userId"],
    "name": ["full_name", "name", "userName"],
    "email": ["email", "email_address"],
    "created_date": ["registration_date", "created_at", "joined"],
    "status": ["status"],
}
FIELDS = ["name", "email", "created_date", "status"]
errors = []


def norm(df):
    ren = {}
    for canon, al in ALIASES.items():
        for a in al:
            if a in df.columns:
                ren[a] = canon
                break
    df = df.rename(columns=ren)
    return df[[c for c in ALIASES if c in df.columns]].copy()


def clean(v):
    if v is None or pd.isna(v):
        return None
    t = str(v).strip()
    return t or None


# ---- rebuild expectation from raw inputs ----
raw = {
    "source_a": norm(pd.read_json(os.path.join(BASE, "data/source_a/users.json"))),
    "source_b": norm(pd.read_csv(os.path.join(BASE, "data/source_b/users.csv"))),
    "source_c": norm(pd.read_parquet(os.path.join(BASE, "data/source_c/users.parquet"))),
}
recs = {}
for s in SOURCES:
    for r in raw[s].to_dict(orient="records"):
        if r.get("user_id") is None or pd.isna(r["user_id"]):
            continue
        recs.setdefault(int(r["user_id"]), {})[s] = {f: clean(r.get(f)) for f in FIELDS}

exp_rows, exp_conf = [], []
for uid in sorted(recs):
    row = {"user_id": uid}
    for f in FIELDS:
        present = {s: recs[uid][s][f] for s in SOURCES
                   if s in recs[uid] and recs[uid][s].get(f) is not None}
        distinct = set(present.values())
        if len(distinct) >= 2:
            sel = next(present[s] for s in SOURCES if s in present)
            exp_conf.append({"user_id": uid, "field": f, "values": present, "selected": sel})
        else:
            sel = next(iter(distinct)) if distinct else None
        if sel is not None:
            row[f] = sel
    if "created_date" in row:
        row["created_date"] = pd.to_datetime(row["created_date"]).strftime("%Y-%m-%d")
    exp_rows.append(row)

# ---- load artifacts ----
pq = os.path.join(BASE, "merged_users.parquet")
cj = os.path.join(BASE, "conflicts.json")
if not os.path.exists(pq):
    errors.append("merged_users.parquet missing")
if not os.path.exists(cj):
    errors.append("conflicts.json missing")
if errors:
    print("FAIL:", errors)
    sys.exit(1)

got = pd.read_parquet(pq)
with open(cj, encoding="utf-8") as fh:
    rep = json.load(fh)

# schema / dtype checks
if list(got.columns) != ["user_id", "name", "email", "created_date", "status"]:
    errors.append(f"columns wrong: {list(got.columns)}")
if str(got["user_id"].dtype) != "int64":
    errors.append(f"user_id dtype not integer: {got['user_id'].dtype}")
if not got["user_id"].is_monotonic_increasing:
    errors.append("user_id not sorted ascending")
if got["user_id"].duplicated().any():
    errors.append("duplicate user_id rows")
for c in ["name", "email", "created_date"]:
    if c in got.columns and not all(isinstance(v, str) for v in got[c]):
        errors.append(f"{c} contains non-string values")
bad_dates = [v for v in got["created_date"] if not (isinstance(v, str) and len(v) == 10
             and v[4] == "-" and v[7] == "-")]
if bad_dates:
    errors.append(f"created_date not YYYY-MM-DD: {bad_dates[:5]}")

# value comparison
exp = pd.DataFrame(exp_rows)
for c in ["name", "email", "created_date", "status"]:
    if c not in exp.columns:
        exp[c] = None
exp = exp[["user_id", "name", "email", "created_date", "status"]].sort_values("user_id")
got_s = got.sort_values("user_id").reset_index(drop=True)
exp_s = exp.reset_index(drop=True)
if len(got_s) != len(exp_s):
    errors.append(f"row count {len(got_s)} != expected {len(exp_s)}")
else:
    for i in range(len(exp_s)):
        for c in exp_s.columns:
            g, e = got_s.at[i, c], exp_s.at[i, c]
            g = None if (g is None or (isinstance(g, float) and pd.isna(g))) else g
            e = None if (e is None or (isinstance(e, float) and pd.isna(e))) else e
            if g != e:
                errors.append(f"row {i} col {c}: got {g!r} expected {e!r}")

# conflict report checks
if not isinstance(rep, dict) or "total_conflicts" not in rep or "conflicts" not in rep:
    errors.append("conflicts.json missing required keys")
else:
    if rep["total_conflicts"] != len(rep["conflicts"]):
        errors.append("total_conflicts != len(conflicts)")
    if rep["total_conflicts"] != len(exp_conf):
        errors.append(f"total_conflicts {rep['total_conflicts']} != expected {len(exp_conf)}")
    key = lambda c: (c["user_id"], c["field"])
    gset = sorted((key(c), json.dumps(c["values"], sort_keys=True), c["selected"])
                  for c in rep["conflicts"])
    eset = sorted((key(c), json.dumps(c["values"], sort_keys=True), c["selected"])
                  for c in exp_conf)
    if gset != eset:
        errors.append(f"conflict entries differ:\n got={gset}\n exp={eset}")

if errors:
    print("FAIL")
    for e in errors:
        print(" -", e)
    sys.exit(1)
print(f"OK users={len(got_s)} conflicts={rep['total_conflicts']}")
","truncated":false}

